 return side==='e'?`<section class="life-panel enemy-life theme-${theme}" id="enemy-health" aria-label="敌方生命 ${G.ehp}/7"><div class="life-title"><span>${life.name}</span><b>${G.ehp}<small> / 7</small></b></div><div class="life-tokens">${Array.from({length:7},(_,i)=>`<svg class="life-token ${i<G.ehp?'lit':'spent'}" viewBox="0 0 36 38" aria-hidden="true">${life.icon}</svg>`).join('')}</div></section>`:`<section class="life-panel player-life" id="player-health" aria-label="玩家生命 ${hp}/7"><div class="bonfire-stage"><img class="bonfire" src="${hp&&!matchMedia('(prefers-reduced-motion:reduce)').matches?BONFIRE_GIF:BONFIRE_STILL}" alt="${hp?hp+'档燃烧篝火':'篝火熄灭'}" style="--fire-size:${hp?(.38+hp*.088):.38};${hp?'':'filter:grayscale(1) brightness(.3);opacity:.5'}"></div><div class="candle-panel"><div class="life-title"><span>不灭薪火</span><b>${hp}<small> / 7</small></b></div><div class="candles">${Array.from({length:7},(_,i)=>`<span class="candle ${i<hp?'burning':'out'}" style="--delay:-${i*.23}s" aria-hidden="true"><i class="wick"></i><i class="candle-flame"></i></span>`).join('')}</div></div></section>`;
