    h+=`<div class="hdr"><span>${G.st.n}</span><span>余灰 ${Math.min(5,grave.length)} 张</span><span>牌堆 ${G.draw.length}</span><span data-a="mute" style="cursor:pointer">${mute?'音效关':'音效开'}</span><span data-a="mus" style="cursor:pointer">${mmute?'音乐关':'音乐开'}</span></div>`;
    h+=healthHTML('e');
