function bossAbilityStateLabel(){const cfg=bossAbilityForStage(),state=bossSkillState();if(!cfg)return '无主动技能';if(G.turn<2)return '第2回合启用';if(bossAbilityUsed())return '本回合已使用';if(!bossSkillReady(state))return '冷却中 · 本回合休息';if(bossSkillAshIndex('e')<0)return '缺少1张可用手牌余灰';if(G.busy)return cfg.timing==='after_attack'?'攻击结束时判定':'部署阶段判定';return cfg.timing==='after_attack'?'等待攻击结束':G.enemyDeployedTurn!==G.turn?'等待Boss部署':'条件不足，本回合未使用'}
