 const fields={p:'e',e:'p',hand:'eh',eh:'hand',draw:'ed',ed:'draw',hp:'ehp',ehp:'hp'},discard=owner==='p'?new Proxy({}, {get:(_,key)=>G.discard?.[map(key)],set:(_,key,value)=>{G.discard[map(key)]=value;return true}}):null;
 const view=owner==='e'?G:new Proxy(G,{get:(target,key)=>key==='discard'?discard:key==='bossSkill'?state:target[fields[key]||key],set:(target,key,value)=>{target[fields[key]||key]=value;return true}});
 return {G:view,state,owner,units:side=>bossUnits(map(side)),choose:bossChoose,shield:bossShield,temp:bossTemp,buff:bossBuff,effect:bossEffect,deferred:bossDeferred,healCard:bossHealCard,healHero:(side,n)=>bossHealHero(map(side),n),discardOne:(side='e')=>bossDiscardOne(map(side)),draw:(side,n)=>bossDraw(map(side),n),consumeDiscard:(side,predicate)=>bossConsumeDiscard(map(side),predicate),summon:(side,template,opts)=>bossSummon(map(side),source?.game?{...template,game:source.game,f:source.f}:template,opts),move:(side,...args)=>bossMove(map(side),...args),returnToHand:(side,card)=>bossReturnToHand(map(side),card),ash:card=>bossAsh(card,owner),redirect:(card,n)=>bossRedirect(card,n,state),cleanse:bossCleanse,hasSkill:bossHasSkill,hurt:(side,...args)=>bossTakeCardDamage(map(side),...args),kill:(side,...args)=>kill(map(side),...args),lockUntil:()=>bossPlayerLockUntil(owner),forecast:owner==='e'&&typeof openingForecast==='function'?()=>openingForecast():null};
