  '冷冽谷的玻尔多':ctx=>{const target=pickBest(ctx,living(ctx,'p',c=>bossCardAttack(c)>0),x=>x.card.a*2+(x.card.mv?2:0));if(!target)return false;ctx.effect(target.card,{lockMove:true,attackReduction:1});return true},
  '教宗沙力万':ctx=>{if(!ctx.G.eh.length||!empty(ctx).length)return false;if(!ctx.discardOne('e'))return false;return !!ctx.summon('e',token('双剑残影',1,1,{at:'暗'}),{expiresTurn:ctx.G.turn,cannotSacrifice:true})},
  '教会野兽':ctx=>{const target=pickBest(ctx,living(ctx,'e',c=>bossCardAttack(c)>0&&c.h<(c.h0??c.h)),x=>x.card.a*2+(x.card.h0-x.card.h));if(!target)return false;ctx.buff(target.card,1);ctx.effect(target.card,{healOnKill:1});return true},
  '格曼':ctx=>{const options=[];for(const unit of living(ctx,'e',c=>c.moved!==ctx.G.turn&&!c.bossEffects?.lockMove))for(const delta of [-1,1]){const other=ctx.G.e[unit.index+delta];if(!other||other.moved===ctx.G.turn||other.bossEffects?.lockMove)continue;const destination=ctx.G.p[unit.index+delta],source=ctx.G.p[unit.index];options.push({...unit,delta,score:unit.card.a*2+(destination?Math.min(unit.card.a,destination.h):unit.card.a)-(source?0:1)})}const selected=pickBest(ctx,options,x=>x.score);if(!selected||!ctx.move('e',selected.card,selected.delta,true))return false;ctx.shield(selected.card,1);return true},
