function portraitEsc(s){return String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}
function portraitHash(s){let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return h>>>0}
function portraitPath(d,fill='var(--portrait-shade)',extra=''){return `<path d="${d}" fill="${fill}" ${extra}/>`}
