function portraitMuzzle(x=40,y=49,rx=14,ry=10){return `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="var(--portrait-paper)"/><ellipse cx="${x-6}" cy="${y-1}" rx="2" ry="1.5" fill="currentColor"/><ellipse cx="${x+6}" cy="${y-1}" rx="2" ry="1.5" fill="currentColor"/><path d="M${x-5} ${y+5}q5 3 10 0" fill="none"/>`}
