function portraitFallback(c){
 const n=String(c?.baseName||c?.n||'');
 if(c?.tokenKind==='spider'||/小蜘蛛/.test(n))return {family:'spider',features:[],label:'召唤小蜘蛛'};
 if(n==='余灰'||/金色余灰|余灰之火/.test(n))return {family:'flame',features:[],label:'余灰祭品'};
 if(n==='骨'||/骨兵|骸骨/.test(n))return {family:'skeleton',features:[],label:'骸骨'};
 if(c?.identity)return {family:'spirit',features:['scar'],label:'死亡身份回响'};
 if(/幼苗|树影分身/.test(n))return {family:'plant',features:[],label:'树影幼苗'};
 if(/幻影|残像|残影/.test(n))return {family:'spirit',features:[],label:'幻影衍生物'};
 if(/风暴鳐/.test(n))return {family:'fish',features:['fin'],label:'风暴鳐鱼'};
 if(/牛头|火牛|野牛|樱牛/.test(n))return {family:'bull',features:[],label:'牛头兽'};
 if(/羊头/.test(n))return {family:'goat',features:[],label:'羊头兽'};
 if(/猿|猴/.test(n))return {family:'monkey',features:[],label:'猿猴'};
 if(/蜘蛛/.test(n))return {family:'spider',features:[],label:'蜘蛛'};
 if(/龙/.test(n))return {family:'dragon',features:[],label:'龙'};
 return {family:'human',features:[],label:'人类角色'};
}
