   const token={a:c.death==='spiders'?0:1,h:1,c:0,at:'物理',token:true},lane=LANE_LIST.filter(j=>!b[side][j]).sort((a,z)=>Math.abs(a-i)-Math.abs(z-i)||a-z)[0];
