// Six campaigns share the same fair, visible-board safety rules. Later worlds
// consider more exchanges, future survivors and the hand's next deployment.
function aiCampaignLevel(){
 const index=DIFFICULTY_ORDER.indexOf(difficulty);
 if(index>=0)return Math.min(5,index);
 return difficulty==='challenge'?5:difficulty==='standard'?2:0;
}
function aiAsh(c){return !!c&&c.c===0&&c.a===0&&(c.fod||c.n==='余灰')}
function aiNormaliseAsh(c){if(aiAsh(c)){c.fod=true;c.e=1;c.a0=0;c.h0=c.h0??1}return c}
function aiPaidPlayBudget(){
 const level=aiCampaignLevel();if(G.turn===1||level<2)return 1;
 if(level===2)return G.lv>=9&&G.turn%3===0?2:1;
 if(level===3)return G.turn%2===0?2:1;
 return 2;
}
function aiFutureValue(c){
 if(!c)return 0;
 const effects=c.bossEffects||{};
 return openingUnitValue(c)+(c.s==='poison'?.6:0)+(c.s==='vamp'?.55:0)+(c.s==='regen'?.45:0)+(c.growth?.7:0)+(c.mv?.3:0)+(c.x==='rekindle'&&!c.rk?.5:0)+(c.dd||0)*.3+(c.death==='spiders'?.7:c.death==='draw'?.6:c.death==='heal'?.35:0)+(effects.shield||0)*.3;
}
function aiSurvivingResources(after,plan){
 const remaining=G.eh.filter((_,i)=>i!==plan.i),bodies=after.e.filter(Boolean);
 const food=bodies.filter(c=>aiAsh(c)||c.fod||c.a===0).length;
 let follow=0;
 for(const c of remaining){if(frozenTurns(c)||c.c===0)continue;const cost=c.c||0;if(cost>food||cost>bodies.length)continue;follow=Math.max(follow,aiFutureValue(c)-cost*.4)}
 return Math.min(follow,8)*.08+Math.min(food,2)*.13;
}
function aiDeploymentPosition(plan,after){
 const c=after.e.find(x=>x?.origin===plan.c);if(!c)return 0;
 const target=G.p[plan.lane],level=aiCampaignLevel();let value=0;
 if(aiAsh(plan.c)){
  // Ash is a next-turn resource: put it where it survives, keep open lanes for
  // combat cards, and do not fill the table with useless fresh sacrifices.
  value+=target?(effectiveCardAttack(target,plan.c)<=0?.12:-.35):.2;
  if(level>=2&&target&&target.c===0)value-=.08;
  value+=Math.max(0,2-Math.abs(plan.lane-2))*.018;
 }else if(level>=1){
  if(c.growth&&target&&!after.p.some(x=>x?.origin===target))value+=.28;
  if(c.s==='guard'&&target?.s==='fly')value+=.35;
  if(c.s==='fly'&&target&&target.s!=='guard')value+=.16;
 }
 return value;
}
function aiChooseDeployment(options={}){
 const level=aiCampaignLevel(),before=openingForecast(),reservedAsh=!options.ignoreSkillReserve&&typeof bossAbilityCanReserveAsh==='function'&&bossAbilityCanReserveAsh()&&typeof bossSkillAshCard==='function'?bossSkillAshCard('e'):null;let choice=null;
 G.eh.forEach((c,i)=>{
  if(c===reservedAsh||frozenTurns(c)||options.ashOnly&&!aiAsh(c)||options.noAsh&&aiAsh(c)||options.noPaid&&c.c>0||options.noZero&&c.c===0&&!aiAsh(c))return;
  let sets=openingSacrificeSets(c);
  if(level===0&&sets.length>1){
   // The first world reads the next exchange but only considers the cheapest
   // sacrifice group. Later worlds search all legal groups, without relaxing
   // protection of a winning lane at any difficulty.
   sets=sets.sort((a,b)=>a.reduce((n,j)=>n+aiFutureValue(G.e[j]),0)-b.reduce((n,j)=>n+aiFutureValue(G.e[j]),0)).slice(0,1);
  }
  for(const sacs of sets)for(const lane of LANE_LIST.filter(j=>!G.e[j]||sacs.includes(j))){
   const plan={c,i,sacs,lane},after=openingForecast(plan);
   if(!openingChoiceAllowed(plan,before,after))continue;
   const gain=after.score-before.score;if(gain<=.15)continue;
   const cost=sacs.reduce((n,j)=>n+(G.e[j].fod?0:aiFutureValue(G.e[j])),0);
   let score=gain-cost*.08+aiDeploymentPosition(plan,after);
   if(level>=2){
    const future=side=>after[side].reduce((n,x)=>n+aiFutureValue(x)-openingUnitValue(x),0);
    score+=(future('e')-future('p'))*(.16+(level-2)*.08);
    score+=aiSurvivingResources(after,plan)*(level-1);
   }
   if(level>=3){
    const survived=after.e.find(x=>x?.origin===c);
    // Evaluate whether the new fighter will still live through the next
    // visible exchange, instead of trading a useful body for a short flash.
    if(survived){const other=after.p[lane];if(other&&effectiveCardAttack(other,survived)>0){const incoming=dealt(other,survived);score+=survived.h>incoming?.16:-.16}else score+=Math.min(survived.a,3)*.08}
   }
   if(level>=4&&c.dr&&G.ed.length)score+=Math.min(c.dr,G.ed.length)*.12;
   if(!choice||score>choice.score+.00001)choice={...plan,score};
  }
 });
 return choice;
}
async function aiDeployChoice(choice,animate){
 if(!choice||!G)return false;
 const {c,i,sacs,lane}=choice,game=G;
 // Recheck the exact live instances before spending: forecast plans are never authority.
 if(!c||!Number.isInteger(i)||G.eh[i]!==c||frozenTurns(c)||!Array.isArray(sacs)||sacs.length!==(c.c||0)||new Set(sacs).size!==sacs.length||!Number.isInteger(lane)||lane<0||lane>=G.e.length||G.e[lane]&&!sacs.includes(lane)||sacs.some(j=>!canSacrificeCard('e',j)))return false;
 G.eh.splice(i,1);
 if(animate&&sacs.length){sacs.forEach(j=>{const node=el('e',j);if(node)burn(node)});snd('burn');await wait(250);if(G!==game)return false}
 const deaths=[];
 for(const j of sacs){const card=G.e[j];kill('e',j,null,'sacrifice',deaths);sacFx(card)}
 aiNormaliseAsh(c);G.e[lane]=c;c.t=G.turn;deaths.forEach(resolveDeath);
 logBattle(`敌方在第${lane+1}格召唤${c.n}`);render();await drawIdle;if(G!==game)return false;
 await enterEffects('e',c);if(G!==game)return false;
 if(typeof bossOnUnitDeploy==='function')bossOnUnitDeploy('e',lane,c);
 if(animate){snd('eplace');await wait(180)}
 return G===game;
}
async function enemyPlay6(animate=true,initial=false){
 if(G.tutorial)return;const game=G;
 if(!initial){
  if(takeCard('e')){render();await drawIdle;if(G!==game)return}
  const ash=takeCard('e',true);aiNormaliseAsh(ash);render();await drawIdle;if(G!==game)return;
 }
 // Zero-cost fighters and the one ash have their own small deployment budget;
 // ash is actually played from hand, and cannot be sacrificed immediately.
 let ashPlayed=false,zeroPlayed=0;
 const paidBudget=aiPaidPlayBudget();let paid=0;
 for(let step=0;step<paidBudget+3;step++){
  const choice=aiChooseDeployment({noAsh:ashPlayed,noPaid:paid>=paidBudget,noZero:zeroPlayed>=1});if(!choice)break;
  if(aiAsh(choice.c)){if(ashPlayed)break;ashPlayed=true}
  else if(choice.c.c===0){if(zeroPlayed>=1)break;zeroPlayed++}
  else{if(paid>=paidBudget)break;paid++}
  if(!await aiDeployChoice(choice,animate)||G.hp<=0||G.ehp<=0)return;
 }
 // A high-scoring paid candidate may have exhausted its budget before the
 // ash candidate was reached. Still provide at most one useful future ash.
 if(!ashPlayed){const ash=aiChooseDeployment({ashOnly:true});if(ash&&!await aiDeployChoice(ash,animate))return}
 if(G!==game)return;const applied=runBossAbility('deploy');render();await drawIdle;
 // A failed deployment power may release its held ash as next-round material.
 // Attack-end powers keep it in hand because their conditions are evaluated later.
 if(G!==game)return;
 if(!applied&&!ashPlayed&&typeof bossAbilityForStage==='function'&&bossAbilityForStage()?.timing==='deploy'){
  const ash=aiChooseDeployment({ashOnly:true,ignoreSkillReserve:true});if(ash)await aiDeployChoice(ash,animate);
 }
}
enemyPlay=enemyPlay6;

// Movement compares both affected columns, including the threat uncovered by
// leaving a lane. It never peeks at the player's hand or spends a winning guard
// merely to chase a larger target.
function aiColumnValue(enemy,player){
 let e=enemy?{...enemy}:null,p=player?{...player}:null,hp=G.hp,ehp=G.ehp;
 const order=typeof battleAttackOrder==='function'?battleAttackOrder():G.turn%2?['p','e']:['e','p'];
 for(const side of order){
  const a=side==='e'?e:p,t=side==='e'?p:e,attack=effectiveCardAttack(a,t);if(!a||attack<=0||a.bossEffects?.skipAttack)continue;
  if(!t||(a.s==='fly'&&t.s!=='guard')){if(side==='e')hp-=attack;else ehp-=attack;continue}
  const damage=dealt(a,t);
  if(t.s==='parry'&&damage<=1)a.h--;else{t.h-=damage;if(t.s==='thorn')a.h--;if(damage>0&&a.s==='vamp')a.h=Math.min(a.h0??a.h,a.h+1)}
  if(e?.h<=0)e=null;if(p?.h<=0)p=null;
 }
 return {score:(G.hp-hp)*3.5-(G.ehp-ehp)*3.5+aiFutureValue(e)-aiFutureValue(p),damage:Math.max(0,G.ehp-ehp),hit:Math.max(0,G.hp-hp),enemy:e,player:p};
}
function aiChooseMove(index){
 const c=G.e[index];if(!c)return null;
 let best=null;const level=aiCampaignLevel();
 for(const d of [-1,1]){
  if(!canMove('e',index,d))continue;const target=index+d,other=G.e[target];
  const beforeA=aiColumnValue(c,G.p[index]),beforeB=aiColumnValue(other,G.p[target]);
  const afterA=aiColumnValue(other,G.p[index]),afterB=aiColumnValue(c,G.p[target]);
  const beforeDamage=beforeA.damage+beforeB.damage,afterDamage=afterA.damage+afterB.damage;
  const remainingDamage=LANE_LIST.filter(j=>j!==index&&j!==target).reduce((n,j)=>n+aiColumnValue(G.e[j],G.p[j]).damage,0);
  if(remainingDamage+afterDamage>=G.ehp&&remainingDamage+beforeDamage<G.ehp)continue;
  if(c.s==='guard'&&G.p[index]?.s==='fly'&&!other&&afterDamage>beforeDamage)continue;
  const score=afterA.score+afterB.score-beforeA.score-beforeB.score;
  if(score>(level<2?1.5:.4)&&(!best||score>best.score))best={d,score};
 }
 return best;
}
async function enemyMoves6(){
 const game=G;
 for(const c of [...G.e]){
  const i=G.e.indexOf(c);if(i<0||!c||!['shift','swap'].includes(c.mv))continue;
  const choice=aiChooseMove(i);if(choice)await moveCard('e',i,choice.d,true);
  if(G!==game)return;
 }
}
enemyMoves=enemyMoves6;
/* Campaign initiative: an original engraved dragon coin, drawn inline for offline play. */
let INITIATIVE_COIN_SESSION = null;

// A short original metallic chime and decelerating ring; effects bus only.
const INITIATIVE_COIN_SOUND_VOICES=new Set();
let initiativeCoinSoundPlays=0;
function stopInitiativeCoinSounds(){for(const voice of [...INITIATIVE_COIN_SOUND_VOICES]){try{voice.source.stop()}catch{}voice.cleanup()}}
function initiativeCoinAudioState(){return {voices:INITIATIVE_COIN_SOUND_VOICES.size,plays:initiativeCoinSoundPlays}}
function playInitiativeCoinSound(phase='toss',seconds=1.05){
 if(document.hidden||typeof mute!=='undefined'&&mute)return false;
 const c=typeof au==='function'?au():null;if(!c||c.state==='closed')return false;
 const now=c.currentTime+.006,output=c.mg||c.destination;
 const note=(frequency,offset,duration,volume,ratio=1)=>{
  let source,gain,voice;
  try{
   source=c.createOscillator();gain=c.createGain();source.type='sine';source.frequency.setValueAtTime(frequency,now+offset);source.frequency.exponentialRampToValueAtTime(frequency*ratio,now+offset+duration);
   gain.gain.setValueAtTime(.00001,now+offset);gain.gain.linearRampToValueAtTime(volume,now+offset+.002);gain.gain.exponentialRampToValueAtTime(.00001,now+offset+duration);
   source.connect(gain);gain.connect(output);let cleaned=false;
   voice={source,cleanup(){if(cleaned)return;cleaned=true;INITIATIVE_COIN_SOUND_VOICES.delete(voice);try{source.disconnect();gain.disconnect()}catch{}}};
   INITIATIVE_COIN_SOUND_VOICES.add(voice);source.onended=voice.cleanup;source.start(now+offset);source.stop(now+offset+duration+.01);
  }catch{try{source?.stop();source?.disconnect();gain?.disconnect()}catch{}if(voice)INITIATIVE_COIN_SOUND_VOICES.delete(voice)}
 };
 initiativeCoinSoundPlays++;
 if(phase==='toss'){
  note(1760,0,.29,.095);note(3529,0,.2,.029);note(5118,.002,.13,.013);
  const span=Math.max(.27,Math.min(1.2,seconds));
  [.09,.15,.225,.315,.425,.55,.69,.825,.94].forEach((x,i)=>{
   const t=x*span,pitch=[2790,3460,2340,3890,2570,3280,2210,3100,2680][i];
   note(pitch,t,.024+i*.003,.024-i*.001,1.025);note(pitch*1.47,t+.002,.018+i*.003,.009-i*.0004,.985);
  });
 }else if(phase==='land'){note(2480,0,.12,.037);note(3717,.025,.11,.016);note(1660,.063,.15,.022)}
 else if(phase==='ash'){note(493.9,0,.18,.021,1.18);note(741,.035,.23,.01,1.12)}
 return true;
}

