 if(!G||ui.game!==G||OV!==null||G.tutorial||(typeof DM!=='undefined'&&DM)||(typeof HOLD_DETAIL!=='undefined'&&HOLD_DETAIL)||(typeof infoPanel!=='undefined'&&infoPanel)){closePlayerBossSkillPopover(false);return}
