 const active=[],extra=[],copies=Object.create(null),gold=new Set();let removedGold=0;
 for(const value of deck){const c=campaignCarryCard(value);if(!c)continue;if(c.rarity==='rare'){if(gold.has(c.n)){removedGold++;continue}gold.add(c.n)}const count=copies[c.n]||0;if(active.length>=DECK_MAX||c.n!=='余灰'&&count>=collectionCopyLimit(c))extra.push(c);else{active.push(c);copies[c.n]=count+1}}
