const WEB_RECORDED_SOUNDS={...SND};
for(const kind of ['draw','shuffle','place','eplace','burn','heal','rare']){
 SND[kind]=()=>{
  if(window.XINHUO_WEB&&window.XINHUO_WEB.audioReady)return WEB_RECORDED_SOUNDS[kind]?.();
  window.XINHUO_WEB?.loadAudio();
  const basic=OLD[kind==='eplace'?'place':kind];
  if(basic)return basic();
  if(kind==='heal'){tone(523,659,.3,'sine',.12);tone(659,784,.4,'sine',.09,.12)}
  else if(kind==='rare'){tone(1046,1046,.8,'sine',.15);tone(1568,1568,.9,'sine',.09,.04)}
 };
}
const webRecordedAttack=playCardAttackSound;
playCardAttackSound=function(card){
 if(window.XINHUO_WEB?.audioReady)return webRecordedAttack(card);
 window.XINHUO_WEB?.loadAudio();return OLD.hit();
};

